"""Bring the database schema to head — on an empty OR an existing database.

    python migrations/bootstrap.py

Why not plain `alembic upgrade head`: the first revision (2161300d6e7c,
"initial schema") was autogenerated as a diff against a database that already
had the base tables (users, profiles, listings, ...) from the old
create_all-on-boot. Replaying the chain on an EMPTY database therefore fails
("relation users does not exist").

This follows Alembic's documented recipe for building a database from
scratch: create every table from the models, then stamp the revision as head
so later migrations apply normally. Existing databases (e.g. Supabase) take
the ordinary upgrade path, unchanged.

Used by the compose `migrate` service and the Helm pre-upgrade Job.
"""

from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
for path in (str(ROOT), str(ROOT / "backend")):
    if path not in sys.path:
        sys.path.insert(0, path)

from alembic import command  # noqa: E402
from alembic.config import Config  # noqa: E402
from sqlalchemy import inspect  # noqa: E402

from shared.database import engine  # noqa: E402
from shared.models import Base  # noqa: E402


def main() -> None:
    cfg = Config(str(ROOT / "alembic.ini"))
    cfg.set_main_option("script_location", str(ROOT / "migrations"))

    existing = set(inspect(engine).get_table_names()) - {"alembic_version"}
    if not existing:
        print("bootstrap: empty database: creating schema from models, stamping head", flush=True)
        Base.metadata.create_all(engine)
        command.stamp(cfg, "head")
    else:
        print(f"bootstrap: {len(existing)} tables found: alembic upgrade head", flush=True)
        command.upgrade(cfg, "head")


if __name__ == "__main__":
    main()
